 WebLogDetailMapper mapper=(WebLogDetailMapper)Proxy.newProxyInstance(WebLogDetailMapper.class.getClassLoader(),new Class<?>[]{WebLogDetailMapper.class},(p,m,a)->{if(m.getName().equals("queryById")){for(WebLogDetailDTO d:details)if(d.getId()==(Long)a[0])return d;return null;}List<WebLogDetailDTO> out=new ArrayList<>();for(WebLogDetailDTO d:details){if(m.getName().equals("queryByIds")&&((List<Long>)a[0]).contains(d.getId()))out.add(d);if(m.getName().equals("match")&&d.getTaskId()==(Long)a[0]&&d.getMinuteOffset()>=(Integer)a[1]&&d.getMinuteOffset()<=(Integer)a[2]&&(((List<Integer>)a[3]).isEmpty()||((List<Integer>)a[3]).contains(d.getLogType())))out.add(d);}return out;});
 WebLogDetailServiceImpl detailService=new WebLogDetailServiceImpl();field(detailService,"detailMapper",mapper);WebLogController controller=new WebLogController();field(controller,"webTaskService",tasks);field(controller,"webLogDetailService",detailService);field(controller,"batchInsertService",detailService);WebLogUploadController upload=new WebLogUploadController();field(upload,"webTaskService",tasks);
 MockMvc mvc=MockMvcBuilders.standaloneSetup(controller,upload).addFilters(new CharacterEncodingFilter("utf-8"),new CORSFilter()).build();Field af=org.springframework.web.servlet.DispatcherServlet.class.getDeclaredField("handlerAdapters");af.setAccessible(true);List<org.springframework.web.servlet.HandlerAdapter> adapters=new ArrayList<>((List<org.springframework.web.servlet.HandlerAdapter>)af.get(mvc.getDispatcherServlet()));adapters.add(new org.springframework.web.servlet.mvc.HttpRequestHandlerAdapter());af.set(mvc.getDispatcherServlet(),adapters);
 List<Map<String,Object>> out=new ArrayList<>();String valid="{\"deviceId\":\"d\",\"logPageNo\":1,\"fileDate\":\"2021-01-01\",\"logArray\":\"%7B%5C%22l%5C%22%3A%5C%22eA%3D%3D%5C%22%7D\"}".replace("%5C%22","%22");
 out.add(capture(mvc,"upload-valid","POST","/logan/web/upload.json",valid));save.set(false);out.add(capture(mvc,"upload-save-error","POST","/logan/web/upload.json",valid));out.add(capture(mvc,"upload-invalid","POST","/logan/web/upload.json","{}"));out.add(capture(mvc,"upload-null","POST","/logan/web/upload.json","null"));out.add(capture(mvc,"upload-invalid-date","POST","/logan/web/upload.json",valid.replace("2021-01-01","bad")));out.add(capture(mvc,"upload-malformed","POST","/logan/web/upload.json","{"));
 for(String[] c:new String[][]{{"index-time","/detailIndex.json?tasks=1,2&beginTime=x:x&endTime=8:00"},{"details-zero","/details.json?detailIds=0,7,7"},{"task-negative","/taskDetail.json?tasks=-1"},{"download-empty-param","/download.json?tasks="},{"search","/search.json?beginTime=1&endTime=2000&deviceId=d"},{"search-invalid","/search.json?beginTime=0&endTime=0"},{"search-binding","/search.json?beginTime=x&endTime=0"},{"latest","/latest.json"},{"task","/taskDetail.json?tasks=1,2"},{"task-invalid","/taskDetail.json?tasks=abc"},{"index","/detailIndex.json?tasks=1,2"},{"index-keyword","/detailIndex.json?tasks=1,2&keyword=hello"},{"index-types","/detailIndex.json?tasks=1,2&logTypes=2"},{"index-empty","/detailIndex.json?tasks=404"},{"details-holes","/details.json?detailIds=8,404,7,8"},{"details-empty","/details.json"},{"detail","/logDetail.json?detailId=7"},{"detail-invalid","/logDetail.json?detailId=x"},{"exception","/exception.json"},{"download-url","/getDownLoadUrl.json?tasks=2,1"},{"download-url-null","/getDownLoadUrl.json"},{"download","/download.json?tasks=1,2"},{"download-empty","/download.json"}}){for(WebLogTaskDTO t:rows)t.setTasks(null);out.add(capture(mvc,c[0],"GET","/logan/web"+c[1],null));}out.add(capture(mvc,"preflight","OPTIONS","/logan/web/upload.json",null));
 save.set(true);out.add(capture(mvc,"upload-string-page","POST","/logan/web/upload.json",valid.replace("\"logPageNo\":1","\"logPageNo\":\"1\"")));out.add(capture(mvc,"upload-float-page","POST","/logan/web/upload.json",valid.replace("\"logPageNo\":1","\"logPageNo\":1.5")));out.add(capture(mvc,"upload-number-device","POST","/logan/web/upload.json",valid.replace("\"deviceId\":\"d\"","\"deviceId\":123")));out.add(capture(mvc,"upload-bad-page","POST","/logan/web/upload.json",valid.replace("\"logPageNo\":1","\"logPageNo\":\"bad\"")));assertEquals(34,out.size());Path path=Paths.get("../contract/captures/java-controller/java-web-http.json");Files.createDirectories(path.getParent());new ObjectMapper().writerWithDefaultPrettyPrinter().writeValue(path.toFile(),out);
